export const getUserByEmail = (email) =>
  store.users.find((user) => user.email.toLowerCase() === email.toLowerCase());

export const getHouseholdMembers = (householdId) =>
  store.users.filter((user) => user.householdId === householdId);

export const formatCurrency = (value) => `₹${Number(value).toLocaleString('en-IN')}`;
